import { Box } from "@/shared/ui/layout/Box";

interface OpStateAttrs { "data-op"?: string; "data-mark"?: string; "data-role"?: string }
interface CellOp { op: string; at?: [number, number]; rows?: [number, number]; cols?: [number, number]; as?: string }
interface MatrixFrame { structure: "matrix"; data: number[][]; ops?: CellOp[] }

function cellOpStateAttrs(ops: readonly CellOp[] | undefined, row: number, col: number): OpStateAttrs {
  const attrs: OpStateAttrs = {};
  for (const o of ops ?? []) {
    if (o.at && o.at[0] === row && o.at[1] === col) {
      attrs["data-op"] = o.op;
    } else if (
      o.rows &&
      o.cols &&
      row >= o.rows[0] &&
      row <= o.rows[1] &&
      col >= o.cols[0] &&
      col <= o.cols[1]
    ) {
      if (o.as) attrs["data-mark"] = o.as;
      else attrs["data-op"] = "region";
    }
  }
  return attrs;
}

export function MatrixView({ frame = { structure: "matrix", data: [[1, 2, 3], [4, 5, 6], [7, 8, 9]], ops: [{ op: "read", at: [1, 1] }] } }: { frame?: MatrixFrame }) {
  const { data, ops } = frame;
  const cols = data[0]?.length ?? 0;

  return (
    <Box
      className="matrix-view"
      role="grid"
      aria-label="matrix"
      style={{ gridTemplateColumns: `repeat(${cols}, var(--matrix-cell, 42px))` }}
    >
      {data.map((row, r) =>
        row.map((v, c) => (
          <Box
            key={`${r}-${c}`}
            className="matrix-cell mono"
            role="gridcell"
            {...cellOpStateAttrs(ops, r, c)}
            title={String(v)}
          >
            {v}
          </Box>
        )),
      )}
    </Box>
  );
}
